const defaultSettings:BudgetSettings={apiEnabled:false,organization:'',project:'',creditsConfirmed:false,creditsExpireAt:'',availableCredits:0,paidBalanceAcknowledged:false,autoRechargeAcknowledged:false,perRunLimit:0,monthlyLimit:0,pricePerImage:0,priceValidUntil:'',model:'gpt-image-1.5'};
