  assert(!['failed','reconciled'].includes(claim.outcome),'任务已结束，不能重新执行或写入不同结果',409,'conflict');
  this.db.transaction(()=>{const current=this.verifyHostClaim(runId,input.claimToken);assert(!current.result_hash||current.result_hash===resultHash,'此任务已接收其他结果',409,'conflict');assert(current.outcome!=='completing','结果正在入库，请稍后重试同一结果',409,'conflict');this.db.prepare('UPDATE host_claims SET result_hash=?,completion_request_id=?,outcome=? WHERE run_id=?').run(resultHash,input.requestId,'completing',runId);}).immediate();
