   // Validate before acknowledging durable receipt; malformed output does not consume the claim.
   let meta:sharp.Metadata;try{meta=await sharp(bytes,{limitInputPixels:40_000_000,failOn:'warning'}).metadata();assert(['png','jpeg','webp'].includes(meta.format??'')&&(meta.pages??1)===1,'宿主结果须为静态 PNG、JPEG、WebP');await sharp(bytes,{limitInputPixels:40_000_000,failOn:'warning'}).stats();}catch(error){if(error instanceof AppError)throw error;throw new AppError('宿主图片无法安全解码');}
