 reconcileRun(runId:string,outcome:'not_accepted'|'charged_no_output',note:string):Run {return this.db.transaction(()=>{const run=this.getRun(runId);assert(run.status==='unknown','只有受理状态未知的任务需要人工对账');assert(['not_accepted','charged_no_output'].includes(outcome),'对账结果无效');assert(typeof note==='string'&&note.trim().length>=4&&note.length<=2000,'请填写至少 4 个字符的供应商核对说明');const updated=this.transition(runId,'failed',{error:outcome==='not_accepted'?'用户确认供应商未受理，预算预留已释放。':'用户确认供应商已计费但无可用输出，按保守上界结算。',errorClass:outcome==='not_accepted'?'provider_error':'storage_error',usage:{...run.usage,userReconciliation:{outcome,note,confirmedAt:now()}}});this.settle(runId,outcome==='charged_no_output');if(run.mode==='codex')this.db.prepare('UPDATE host_claims SET outcome=? WHERE run_id=?').run('reconciled',runId);return updated;})();}
 diagnostics(projectId:string){const project=this.getProject(projectId);return {schemaVersion:1,project:{id:project.id,name:project.name,graphRevision:project.graphRevision,nodeCount:project.graph.nodes.length,edgeCount:project.graph.edges.length},runs:this.listRuns(projectId).map(run=>({id:run.id,jobId:run.jobId,nodeId:run.nodeId,status:run.status,mode:run.mode,createdAt:run.createdAt,updatedAt:run.updatedAt,fingerprint:run.fingerprint,providerRequestId:run.providerRequestId,errorClass:run.errorClass,assetVersionIds:run.assetVersionIds,events:run.events})),budget:{reserved:this.budget().reserved,spent:this.budget().spent},assets:this.listAssets(projectId).map(a=>({id:a.id,sha256:a.sha256,runId:a.runId,source:a.source}))};}
