  store.db.prepare("UPDATE canvas_native_jobs SET next_check=? WHERE phase='review' AND owner_pid IS NULL").run(Date.now());
  if (store.db.prepare("SELECT 1 FROM canvas_native_jobs WHERE phase <> 'done' LIMIT 1").get()) startCanvasExecutions(store);
